     *
     * @return mixed one array, or an array keyed by A, B, C, D when several results are requested
     */
    public static function zpk2ss(mixed $z, mixed $p, mixed $k): mixed
    {
        return Registry::routine('signal.zpk2ss', [$z, $p, $k]);
    }

